int main(void) {
    int n;
    ll H, A, B;

    /*
      Assumed input format:
      n H A B
      followed by n integers d[i]

      Interpretation:
      - H: required height to escape
      - A: office worker's daytime climb per day
      - B: each other sinner's nightly climb
      - d[i]: initial height of sinner i

      Office worker:
      - starts at height 0
      - each day climbs +A
      - if height >= H during day, escapes immediately
      - otherwise at night he slides back by 1?  (not specified)

      Since the statement provided here is incomplete/ambiguous, we solve the
      standard earliest-escape condition where the danger is only that some
      sinner catches up at the end of a night:
         worker height after day k = k*A
         sinner i height after k nights = d[i] + k*B
      To survive until day k, need for all previous nights t<k:
         t*A > d[i] + t*B
      and on day k:
         k*A >= H

      This reduces to checking whether before the escape day, the maximum sinner
      height stays strictly below the worker's height.

      If A <= B, worker cannot ever increase his lead over sinners; only day 1
      direct escape can work.
    */

    if (scanf("%d %lld %lld %lld", &n, &H, &A, &B) != 4) return 0;

    ll maxd = -(1LL << 60);
    for (int i = 0; i < n; ++i) {
        ll x;
        scanf("%lld", &x);
        if (x > maxd) maxd = x;
    }

    /* Earliest day to reach H during daytime */
    ll k_escape = (H + A - 1) / A;

    /* Escape on day 1 before any night check */
    if (k_escape == 1) {
        printf("1\n");
        return 0;
    }

    /* Must survive nights 1..k_escape-1:
       for every t in [1, k_escape-1], need t*A > maxd + t*B
       i.e. t*(A-B) > maxd
       Since lhs increases with t when A>B, hardest is t=1? Actually smallest t.
       Need all t, so need 1*(A-B) > maxd for t=1 if increasing.
    */
    if (A <= B) {
        printf("-1\n");
        return 0;
    }

    ll diff = A - B;
    if (diff > maxd) {
        printf("%lld\n", k_escape);
    } else {
        printf("-1\n");
    }

    return 0;
}

