import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();

        int n;
        try {
            n = fs.nextInt();
        } catch (Exception e) {
            return;
        }

        long h = fs.nextLong();
        long[] a = new long[n];
        long[] b = new long[n];

        for (int i = 0; i < n; i++) a[i] = fs.nextLong();
        for (int i = 0; i < n; i++) b[i] = fs.nextLong();

        /*
         Assumed standard model:
         - Height to escape: h
         - On each day i, worker climbs a[i]
         - If after daytime position >= h, he escapes that day
         - Otherwise, during the night he slides down by b[i]
         - Need earliest escape day, else -1

         Since the statement mentions "best order of energy drinks", we interpret
         that days/drinks can be reordered arbitrarily. To minimize escape day:
         - maximize cumulative daytime gains as early as possible
         - each used day contributes net gain (a[i] - b[i]) if not escaping that day
         Greedy:
         Sort by net gain descending for prefix usefulness, but also large a[i] can
         help immediate escape. A safe optimal strategy for earliest day is:
         consider each drink as the final day, and before it use drinks with largest
         net gains.
        */

        long maxA = 0;
        for (long x : a) maxA = Math.max(maxA, x);
        if (maxA >= h) {
            System.out.println(1);
            return;
        }

        long[] net = new long[n];
        for (int i = 0; i < n; i++) net[i] = a[i] - b[i];

        Integer[] order = new Integer[n];
        for (int i = 0; i < n; i++) order[i] = i;
        Arrays.sort(order, (i, j) -> Long.compare(net[j], net[i]));

        long[] pref = new long[n + 1];
        for (int i = 0; i < n; i++) {
            pref[i + 1] = pref[i] + net[order[i]];
        }

        long ans = Long.MAX_VALUE;

        // Position before day k final attempt equals sum of best (k-1) net gains.
        // Need position + a[last] >= h.
        // For each possible final drink, find minimal k such that
        // pref[k-1] >= h - a[last]
        for (int i = 0; i < n; i++) {
            long need = h - a[i];
            if (need <= 0) {
                ans = 1;
                break;
            }

            int l = 0, r = n;
            while (l < r) {
                int m = (l + r) >>> 1;
                if (pref[m] >= need) r = m;
                else l = m + 1;
            }

            // Need l previous days. Total day count = l + 1.
            // But if drink i is among those l chosen previous drinks, we need one more
            // because final drink must be distinct.
            int posInOrder = -1;
            for (int p = 0; p < n; p++) {
                if (order[p] == i) {
                    posInOrder = p;
                    break;
                }
            }

            long days;
            if (l == n) continue;
            if (posInOrder >= 0 && posInOrder < l) {
                if (l + 1 > n) continue;
                days = l + 2L;
            } else {
                days = l + 1L;
            }
            ans = Math.min(ans, days);
        }

        if (ans == Long.MAX_VALUE || ans > n) System.out.println(-1);
        else System.out.println(ans);
    }
}

