int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;

    vector<int> a(n), b(n);
    for (int i = 0; i < n; i++) cin >> a[i] >> b[i];

    // dp[i][j] = maximum height after i days, using j energy drinks
    // j is 0-based index of the last used drink, or -1 if none used
    // We'll store as a pair: (height, day) but we only need height
    // Since n,m <= 100, we can do DP over days and drink usage

    const int INF = -1e9;
    vector<vector<int>> dp(n + 1, vector<int>(m + 1, INF));
    dp[0][0] = 0;

    for (int day = 0; day < n; day++) {
        for (int used = 0; used <= m; used++) {
            if (dp[day][used] == INF) continue;
            int cur = dp[day][used];
            // Option 1: don't use a drink on this day
            int climb = a[day];
            int slide = b[day];
            int next = cur + climb;
            // check if caught by others during night
            // others climb during night: they start at 0 and climb a[day] each night? 
            // Actually problem: "Other sinners can also climb during the night"
            // They climb the same distance as the worker's day climb? Usually each sinner climbs a fixed amount per night.
            // Re-reading: "Other sinners can also climb during the night, and if they catch up to him, the silk will be cut."
            // It means each night, each other sinner climbs some amount (given?). But not specified per sinner.
            // Actually typical problem: during night, the worker slides down b[i], and other sinners climb up a[i] (same as day climb).
            // So if at night, other sinners start from 0 and climb a[i], they reach a[i] height.
            // If worker's height after slide is <= a[i], they catch him.
            // Let's assume that: after climbing during day, worker is at cur + a[day].
            // At night, he slides b[day], so ends at cur + a[day] - b[day].
            // Others climb a[day] during night, so they reach a[day].
            // If worker's end height <= a[day], he gets caught.
            // But also if he escapes (reaches >= 1000000) during day, he's free before night.

            // Check escape during day
            if (next >= 1000000) {
                cout << day + 1 << "\n";
                return 0;
            }
            // Check if caught at night
            int afterNight = next - slide;
            if (afterNight <= a[day]) {
                // caught, cannot proceed
                continue;
            }
            dp[day + 1][used] = max(dp[day + 1][used], afterNight);

            // Option 2: use a drink on this day (if any left)
            if (used < m) {
                int climb2 = a[day] * 2; // double energy
                int slide2 = b[day];
                int next2 = cur + climb2;
                if (next2 >= 1000000) {
                    cout << day + 1 << "\n";
                    return 0;
                }
                int afterNight2 = next2 - slide2;
                if (afterNight2 <= a[day]) continue;
                dp[day + 1][used + 1] = max(dp[day + 1][used + 1], afterNight2);
            }
        }
    }

    // If we exhaust all days without escaping
    cout << -1 << "\n";

    return 0;
}

